<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit,Authorization};
final class Roles {
 public static function grant(\PDO $p,int $u,int $programme,int $target,int $role,string $expires,string $reason):void {
  Core::tx($p,function()use($p,$u,$programme,$target,$role,$expires,$reason){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'roles.manage',$r);$actor=Policy::actor($p,$u);$staff=Policy::actor($p,$target);if($u===$target&&!Authorization::super($p,$u))throw new \RuntimeException('Tidak boleh delegasi kepada diri sendiri.');$rr=Database::query($p,"SELECT * FROM roles WHERE id=? AND module_code='training' AND is_active=1 AND code IN ('training_programme_admin','training_approver')",[$role])->fetch();if(!$rr)throw new \RuntimeException('Role program tidak sah.');if(!Authorization::super($p,$u)){if(!Authorization::allowed($p,$u,'training.roles.manage',(int)$r['owner_organisation_id']))throw new \RuntimeException('Delegasi memerlukan scope organisasi.');if(!Authorization::allowed($p,$u,'core.staff.view',(int)$staff['organisation_id']))throw new \RuntimeException('Target di luar scope staf.');foreach(Database::query($p,'SELECT pp.code FROM role_permissions rp JOIN permissions pp ON pp.id=rp.permission_id WHERE rp.role_id=?',[$role])->fetchAll() as $perm)if(!Policy::allowed($p,$u,substr($perm['code'],9),$r))throw new \RuntimeException('Delegasi melebihi permission sendiri.');}
   $date=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$expires,new \DateTimeZone('UTC'));if(!$date||$date->format('Y-m-d H:i:s')!==$expires||$expires<=gmdate('Y-m-d H:i:s')||$expires>gmdate('Y-m-d H:i:s',time()+366*86400))throw new \InvalidArgumentException('Tempoh role mesti sah, maksimum setahun.');$reason=Core::text($reason,500);Database::query($p,'INSERT INTO training_access_assignments(programme_id,user_id,role_id,assigned_by,expires_at,reason) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE assigned_by=VALUES(assigned_by),expires_at=VALUES(expires_at),reason=VALUES(reason),revoked_at=NULL',[$programme,$target,$role,$u,$expires,$reason]);Audit::record($p,'programme.role_granted',$u,(int)$r['owner_organisation_id'],(string)$target,'training',$reason,null,['programme'=>$programme,'role_id'=>$role,'expires_at'=>$expires]);});
 }
 public static function revoke(\PDO $p,int $u,int $programme,int $assignment,string $reason):void {Core::tx($p,function()use($p,$u,$programme,$assignment,$reason){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'roles.manage',$r);$a=Database::query($p,'SELECT * FROM training_access_assignments WHERE id=? AND programme_id=? FOR UPDATE',[$assignment,$programme])->fetch();if(!$a)throw new \RuntimeException('Role tidak wujud.');Database::query($p,'UPDATE training_access_assignments SET revoked_at=UTC_TIMESTAMP() WHERE id=?',[$assignment]);Audit::record($p,'programme.role_revoked',$u,(int)$r['owner_organisation_id'],(string)$a['user_id'],'training',Core::text($reason,500),$a,null);});}
 public static function definition(\PDO $p,int $u,int $programme,string $code,string $name):void {Core::tx($p,function()use($p,$u,$programme,$code,$name){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'participants.manage',$r);if(!preg_match('/\A[a-z][a-z0-9_]{1,63}\z/',$code))throw new \InvalidArgumentException('Kod role tidak sah.');Database::query($p,'INSERT INTO training_participation_roles(programme_id,code,name) VALUES(?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1',[$programme,$code,Core::text($name,100)]);Audit::record($p,'programme.participation_role_defined',$u,(int)$r['owner_organisation_id'],(string)$programme,'training',null,null,['code'=>$code,'name'=>$name]);});}
 public static function participation(\PDO $p,int $u,int $programme,int $registration,int $role,bool $remove=false):void {Core::tx($p,function()use($p,$u,$programme,$registration,$role,$remove){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'participants.manage',$r);if(!Database::query($p,'SELECT 1 FROM training_registrations WHERE id=? AND programme_id=?',[$registration,$programme])->fetchColumn()||!Database::query($p,'SELECT 1 FROM training_participation_roles WHERE id=? AND programme_id=? AND is_active=1',[$role,$programme])->fetchColumn())throw new \RuntimeException('Registration/role bukan program ini.');if($remove)Database::query($p,'DELETE FROM training_participation_assignments WHERE registration_id=? AND role_id=?',[$registration,$role]);else Database::query($p,'INSERT IGNORE INTO training_participation_assignments(registration_id,role_id,assigned_by) VALUES(?,?,?)',[$registration,$role,$u]);Audit::record($p,$remove?'programme.participation_role_revoked':'programme.participation_role_assigned',$u,(int)$r['owner_organisation_id'],(string)$registration,'training',null,null,['role_id'=>$role]);});}
}
